import{_ as l,a0 as p,w as r,s as o,I as t,x as a,a1 as i,A as n,ao as d}from"./chunks/framework.C16IyNjs.js";import"./chunks/theme.CClUzVyq.js";const v=JSON.parse('{"title":"Stratis 加密入門 | LCTT x X-CMD","titleTemplate":false,"description":"Stratis 加密入門 | LCTT (202104) | X-CMD","frontmatter":{"pageClass":"x-lctt","head":[["meta",{"name":"og:title","content":"Stratis 加密入門 | LCTT x X-CMD"}],["meta",{"name":"og:description","content":"Stratis 加密入門 | LCTT (202104) | X-CMD"}]]},"headers":[],"params":{"isLCTT":true,"post":"202104/20201109 Getting started with Stratis encryption","title":"Stratis 加密入門","tag":"202104","desc":""},"relativePath":"202104/20201109 Getting started with Stratis encryption.md","filePath":"[post].md"}'),h={name:"202104/20201109 Getting started with Stratis encryption.md"};function c(k,s,g,b,u,y){const e=p("Link");return r(),o("div",null,[s[22]||(s[22]=t("h1",{id:"stratis-加密入門",tabindex:"-1"},[a("Stratis 加密入門 "),t("a",{class:"header-anchor",href:"#stratis-加密入門","aria-label":"Permalink to “Stratis 加密入門”"},"​")],-1)),s[23]||(s[23]=t("p",null,[t("img",{src:"https://img.linux.net.cn/data/attachment/album/202104/19/094919orzaxwl5axiqqfiu.jpg",alt:""})],-1)),t("p",null,[s[2]||(s[2]=a("Stratis 在其 ",-1)),i(e,{href:"https://stratis-storage.github.io/"},{default:n(()=>[...s[0]||(s[0]=[a("官方網站",-1)])]),_:1}),s[3]||(s[3]=a(" 上被描述為“",-1)),s[4]||(s[4]=t("em",null,"易於使用的 Linux 本地存儲管理",-1)),s[5]||(s[5]=a("”。請看這個 ",-1)),i(e,{href:"https://www.youtube.com/watch?v=CJu3kmY-f5o"},{default:n(()=>[...s[1]||(s[1]=[a("短視頻",-1)])]),_:1}),s[6]||(s[6]=a("，快速演示基礎知識。該視頻是在 Red Hat Enterprise Linux 8 系統上錄製的。視頻中顯示的概念也適用於 Fedora 中的 Stratis。",-1))]),s[24]||(s[24]=d(`<p>Stratis 2.1 版本引入了對加密的支持。繼續閲讀以瞭解如何在 Stratis 中開始加密。</p><h3 id="先決條件" tabindex="-1">先決條件 <a class="header-anchor" href="#先決條件" aria-label="Permalink to “先決條件”">​</a></h3><p>加密需要 Stratis 2.1 或更高版本。這篇文章中的例子使用的是 Fedora 33 的預發佈版本。Stratis 2.1 將用在 Fedora 33 的最終版本中。</p><p>你還需要至少一個可用的塊設備來創建一個加密池。下面的例子是在 KVM 虛擬機上完成的，虛擬磁盤驅動器為 5GB（<code>/dev/vdb</code>）。</p><h3 id="在內核密鑰環中創建一個密鑰" tabindex="-1">在內核密鑰環中創建一個密鑰 <a class="header-anchor" href="#在內核密鑰環中創建一個密鑰" aria-label="Permalink to “在內核密鑰環中創建一個密鑰”">​</a></h3><p>Linux 內核<ruby>密鑰環<rt>keyring</rt></ruby>用於存儲加密密鑰。關於內核密鑰環的更多信息，請參考 <code>keyrings</code> 手冊頁（<code>man keyrings</code>）。</p><p>使用 <code>stratis key set</code> 命令在內核鑰匙圈中設置密鑰。你必須指定從哪裏讀取密鑰。要從標準輸入中讀取密鑰，使用 <code>-capture-key</code> 選項。要從文件中讀取密鑰，使用 <code>-keyfile-path &lt;file&gt;</code> 選項。最後一個參數是一個密鑰描述。它將稍後你創建加密的 Stratis 池時使用。</p><p>例如，要創建一個描述為 <code>pool1key</code> 的密鑰，並從標準輸入中讀取密鑰，可以輸入：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis key set --capture-key pool1key</span></span>
<span class="line"><span>Enter desired key data followed by the return key:</span></span></code></pre></div><p>該命令提示我們輸入密鑰數據/密碼，然後密鑰就創建在內核密鑰環中了。</p><p>要驗證密鑰是否已被創建，運行 <code>stratis key list</code>：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis key list</span></span>
<span class="line"><span>Key Description</span></span>
<span class="line"><span>pool1key</span></span></code></pre></div><p>這將驗證是否創建了 <code>pool1key</code>。請注意，這些密鑰不是持久的。如果主機重啓，在訪問加密的 Stratis 池之前，需要再次提供密鑰（此過程將在後面介紹）。</p><p>如果你有多個加密池，它們可以有一個單獨的密鑰，也可以共享同一個密鑰。</p><p>也可以使用以下 <code>keyctl</code> 命令查看密鑰：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># keyctl get_persistent @s</span></span>
<span class="line"><span>318044983</span></span>
<span class="line"><span># keyctl show</span></span>
<span class="line"><span>Session Keyring</span></span>
<span class="line"><span> 701701270 --alswrv      0     0  keyring: _ses</span></span>
<span class="line"><span> 649111286 --alswrv      0 65534   \\_ keyring: _uid.0</span></span>
<span class="line"><span> 318044983 ---lswrv      0 65534   \\_ keyring: _persistent.0</span></span>
<span class="line"><span>1051260141 --alswrv      0     0       \\_ user: stratis-1-key-pool1key</span></span></code></pre></div><h3 id="創建加密的-stratis-池" tabindex="-1">創建加密的 Stratis 池 <a class="header-anchor" href="#創建加密的-stratis-池" aria-label="Permalink to “創建加密的 Stratis 池”">​</a></h3><p>現在已經為 Stratis 創建了一個密鑰，下一步是創建加密的 Stratis 池。加密池只能在創建池時進行。目前不可能對現有的池進行加密。</p><p>使用 <code>stratis pool create</code> 命令創建一個池。添加 <code>-key-desc</code> 和你在上一步提供的密鑰描述（<code>pool1key</code>）。這將向 Stratis 發出信號，池應該使用提供的密鑰進行加密。下面的例子是在 <code>/dev/vdb</code> 上創建 Stratis 池，並將其命名為 <code>pool1</code>。確保在你的系統中指定一個空的/可用的設備。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool create --key-desc pool1key pool1 /dev/vdb</span></span></code></pre></div><p>你可以使用 <code>stratis pool list</code> 命令驗證該池是否已經創建：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool list</span></span>
<span class="line"><span>Name                     Total Physical   Properties</span></span>
<span class="line"><span>pool1   4.98 GiB / 37.63 MiB / 4.95 GiB      ~Ca, Cr</span></span></code></pre></div><p>在上面顯示的示例輸出中，<code>~Ca</code> 表示禁用了緩存（<code>~</code> 否定了該屬性）。<code>Cr</code> 表示啓用了加密。請注意，緩存和加密是相互排斥的。這兩個功能不能同時啓用。</p><p>接下來，創建一個文件系統。下面的例子演示了創建一個名為 <code>filesystem1</code> 的文件系統，將其掛載在 <code>/filesystem1</code> 掛載點上，並在新文件系統中創建一個測試文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis filesystem create pool1 filesystem1</span></span>
<span class="line"><span># mkdir /filesystem1</span></span>
<span class="line"><span># mount /stratis/pool1/filesystem1 /filesystem1</span></span>
<span class="line"><span># cd /filesystem1</span></span>
<span class="line"><span># echo &quot;this is a test file&quot; &gt; testfile</span></span></code></pre></div><h3 id="重啓後訪問加密池" tabindex="-1">重啓後訪問加密池 <a class="header-anchor" href="#重啓後訪問加密池" aria-label="Permalink to “重啓後訪問加密池”">​</a></h3><p>當重新啓動時，你會發現 Stratis 不再顯示你的加密池或它的塊設備：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool list</span></span>
<span class="line"><span>Name   Total Physical   Properties</span></span></code></pre></div><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis blockdev list</span></span>
<span class="line"><span>Pool Name   Device Node   Physical Size   Tier</span></span></code></pre></div><p>要訪問加密池，首先要用之前使用的相同的密鑰描述和密鑰數據/口令重新創建密鑰：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis key set --capture-key pool1key</span></span>
<span class="line"><span>Enter desired key data followed by the return key:</span></span></code></pre></div><p>接下來，運行 <code>stratis pool unlock</code> 命令，並驗證現在可以看到池和它的塊設備：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># stratis pool unlock</span></span>
<span class="line"><span># stratis pool list</span></span>
<span class="line"><span>Name                      Total Physical   Properties</span></span>
<span class="line"><span>pool1   4.98 GiB / 583.65 MiB / 4.41 GiB      ~Ca, Cr</span></span>
<span class="line"><span># stratis blockdev list</span></span>
<span class="line"><span>Pool Name   Device Node   Physical Size   Tier</span></span>
<span class="line"><span>pool1       /dev/dm-2          4.98 GiB   Data</span></span></code></pre></div><p>接下來，掛載文件系統並驗證是否可以訪問之前創建的測試文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># mount /stratis/pool1/filesystem1 /filesystem1/</span></span>
<span class="line"><span># cat /filesystem1/testfile</span></span>
<span class="line"><span>this is a test file</span></span></code></pre></div><h3 id="使用-systemd-單元文件在啓動時自動解鎖-stratis-池" tabindex="-1">使用 systemd 單元文件在啓動時自動解鎖 Stratis 池 <a class="header-anchor" href="#使用-systemd-單元文件在啓動時自動解鎖-stratis-池" aria-label="Permalink to “使用 systemd 單元文件在啓動時自動解鎖 Stratis 池”">​</a></h3><p>可以在啓動時自動解鎖 Stratis 池，無需手動干預。但是，必須有一個包含密鑰的文件。在某些環境下，將密鑰存儲在文件中可能會有安全問題。</p><p>下圖所示的 systemd 單元文件提供了一個簡單的方法來在啓動時解鎖 Stratis 池並掛載文件系統。歡迎提供更好的/替代方法的反饋。你可以在文章末尾的評論區提供建議。</p><p>首先用下面的命令創建你的密鑰文件。確保用之前輸入的相同的密鑰數據/密碼來代替<code>passphrase</code>。</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># echo -n passphrase &gt; /root/pool1key</span></span></code></pre></div><p>確保該文件只能由 root 讀取：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># chmod 400 /root/pool1key</span></span>
<span class="line"><span># chown root:root /root/pool1key</span></span></code></pre></div><p>在 <code>/etc/systemd/system/stratis-filesystem1.service</code> 創建包含以下內容的 systemd 單元文件：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span>[Unit]</span></span>
<span class="line"><span>Description = stratis mount pool1 filesystem1 file system</span></span>
<span class="line"><span>After = stratisd.service</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Service]</span></span>
<span class="line"><span>ExecStartPre=sleep 2</span></span>
<span class="line"><span>ExecStartPre=stratis key set --keyfile-path /root/pool1key pool1key</span></span>
<span class="line"><span>ExecStartPre=stratis pool unlock</span></span>
<span class="line"><span>ExecStartPre=sleep 3</span></span>
<span class="line"><span>ExecStart=mount /stratis/pool1/filesystem1 /filesystem1</span></span>
<span class="line"><span>RemainAfterExit=yes</span></span>
<span class="line"><span></span></span>
<span class="line"><span>[Install]</span></span>
<span class="line"><span>WantedBy = multi-user.target</span></span></code></pre></div><p>接下來，啓用服務，使其在啓動時運行：</p><div class="language-"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark" style="--shiki-light:#24292e;--shiki-dark:#e1e4e8;--shiki-light-bg:#fff;--shiki-dark-bg:#24292e;" tabindex="0" dir="ltr"><code><span class="line"><span># systemctl enable stratis-filesystem1.service</span></span></code></pre></div><p>現在重新啓動並驗證 Stratis 池是否已自動解鎖，其文件系統是否已掛載。</p><h3 id="結語" tabindex="-1">結語 <a class="header-anchor" href="#結語" aria-label="Permalink to “結語”">​</a></h3><p>在今天的環境中，加密是很多人和組織的必修課。本篇文章演示瞭如何在 Stratis 2.1 中啓用加密功能。</p><hr>`,50)),t("p",null,[s[8]||(s[8]=a("via: ",-1)),i(e,{href:"https://fedoramagazine.org/getting-started-with-stratis-encryption/"},{default:n(()=>[...s[7]||(s[7]=[a("https://fedoramagazine.org/getting-started-with-stratis-encryption/",-1)])]),_:1})]),t("p",null,[s[13]||(s[13]=a("作者：",-1)),i(e,{href:"https://fedoramagazine.org/author/briansmith/"},{default:n(()=>[...s[9]||(s[9]=[a("briansmith",-1)])]),_:1}),s[14]||(s[14]=a(" 選題：",-1)),i(e,{href:"https://github.com/lujun9972"},{default:n(()=>[...s[10]||(s[10]=[a("lujun9972",-1)])]),_:1}),s[15]||(s[15]=a(" 譯者：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[11]||(s[11]=[a("wxy",-1)])]),_:1}),s[16]||(s[16]=a(" 校對：",-1)),i(e,{href:"https://github.com/wxy"},{default:n(()=>[...s[12]||(s[12]=[a("wxy",-1)])]),_:1})]),t("p",null,[s[19]||(s[19]=a("本文由 ",-1)),i(e,{href:"https://github.com/LCTT/TranslateProject"},{default:n(()=>[...s[17]||(s[17]=[a("LCTT",-1)])]),_:1}),s[20]||(s[20]=a(" 原創編譯，",-1)),i(e,{href:"https://linux.cn/"},{default:n(()=>[...s[18]||(s[18]=[a("Linux中國",-1)])]),_:1}),s[21]||(s[21]=a(" 榮譽推出",-1))])])}const C=l(h,[["render",c]]);export{v as __pageData,C as default};
